+void Notifications::collapseBursts(int maximum)
+{
+    QHash<QString, QList<QModelIndex>> notificationsByApplication;
+    for (int i = 0, count = d->filterModel->rowCount(); i < count; ++i) {
+        const QModelIndex idx = d->filterModel->index(i, 0);
+        if (idx.data(Notifications::TypeRole).toInt() != Notifications::NotificationType || idx.data(Notifications::ExpiredRole).toBool()
+            || idx.data(Notifications::UrgencyRole).toInt() == Notifications::CriticalUrgency) {
+            continue;
+        }
+        QString application = idx.data(Notifications::DesktopEntryRole).toString();
+        if (application.isEmpty()) {
+            application = idx.data(Notifications::ApplicationNameRole).toString();
+        }
+        notificationsByApplication[application].append(idx);
+    }
+
+    for (auto it = notificationsByApplication.begin(); it != notificationsByApplication.end(); ++it) {
+        QList<QModelIndex> &notifications = it.value();
+        Private::BurstSummary &summary = d->burstSummaries[it.key()];
+        // The summary takes the place of one of the popups.
+        const int kept = maximum - 1;
+        if (notifications.count() <= (summary.notification ? kept : maximum)) {
+            continue;
+        }
+
+        std::stable_sort(notifications.begin(), notifications.end(), [](const QModelIndex &a, const QModelIndex &b) {
+            return a.data(Notifications::CreatedRole).toDateTime() < b.data(Notifications::CreatedRole).toDateTime();
+        });
+
+        const QModelIndex firstIdx = notifications.first();
+        const QString applicationName = firstIdx.data(Notifications::ApplicationNameRole).toString();
+        const QString applicationIconName = firstIdx.data(Notifications::ApplicationIconNameRole).toString();
+
+        // Keep the oldest ones, which are already shown, and only put the rest in the history.
+        QList<QPersistentModelIndex> collapsed;
+        for (int i = kept; i < notifications.count(); ++i) {
+            collapsed.append(d->filterModel->mapToSource(notifications.at(i)));
+        }
+        for (const QPersistentModelIndex &idx : std::as_const(collapsed)) {
+            d->notificationsAndJobsModel->setData(idx, true, Notifications::ExpiredRole);
+        }
+
+        if (!summary.notification) {
+            summary.count = 0;
+        }
+        summary.count += collapsed.count();
+
+        const QString text = i18ncp("@info", "%1 more notification from %2", "%1 more notifications from %2", summary.count, applicationName);
+        if (summary.notification) {
+            summary.notification->setText(text);
+            continue;
+        }
+
+        summary.notification = new KNotification(u"burstSummary"_s);
+        summary.notification->setTitle(applicationName);
+        summary.notification->setText(text);
+        summary.notification->setIconName(applicationIconName.isEmpty() ? u"preferences-desktop-notification-bell"_s : applicationIconName);
+        summary.notification->setFlags(KNotification::CloseOnTimeout);
+        summary.notification->setComponentName(u"libnotificationmanager"_s);
+        summary.notification->setHint(u"transient"_s, true);
+
+        const QString showNotificationsText = i18nc("@action:button Show the notifications popup", "Show Notifications");
+
+        const KNotificationAction *defaultShowNotificationsAction = summary.notification->addDefaultAction(showNotificationsText);
+        connect(defaultShowNotificationsAction, &KNotificationAction::activated, this, &Notifications::showNotificationsRequested);
+
+        const KNotificationAction *showNotificationsAction = summary.notification->addAction(showNotificationsText);
+        connect(showNotificationsAction, &KNotificationAction::activated, this, &Notifications::showNotificationsRequested);
+
+        summary.notification->sendEvent();
+    }
+}
